# tools/replay_uploader/batcher.py
import json
from .client import post_batch

BATCH_SIZE = 500

def chunks(scores, n=BATCH_SIZE):
    for i in range(0, len(scores), n):
        yield scores[i:i + n]

def upload(scores):
    for chunk in chunks(scores):
        body = json.dumps({"scores": chunk}).encode()
        post_batch("/v2/scores:batch", body)
